


BEGIN;
SELECT pg_advisory_xact_lock(20261007, 961);
CREATE OR REPLACE FUNCTION pg_temp.cargar_catalogos(lote jsonb)
RETURNS integer LANGUAGE plpgsql AS $fn$
DECLARE
 r jsonb; fabricante_uuid uuid; motor_uuid uuid; repuesto_uuid uuid;
 codigo_motor text; nombre_modelo text; referencia text; cantidad integer; cargados integer := 0;
BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements(lote) LOOP
  SELECT count(*), (array_agg(id))[1] INTO cantidad, fabricante_uuid
    FROM public.fabricantes WHERE upper(btrim(nombre))=upper(btrim(r->>'fabricante'));
  IF cantidad>1 THEN RAISE EXCEPTION 'Fabricante duplicado: %; resolver antes de importar',r->>'fabricante'; END IF;
  IF cantidad=0 THEN
   INSERT INTO public.fabricantes(nombre,tipo) VALUES(r->>'fabricante','OEM') RETURNING id INTO fabricante_uuid;
  END IF;
  
  INSERT INTO public.repuestos_tecnicos
   (catalogo_origen,fuente_registro_id,codigo_catalogo,codigo_oem,nombre,subsistema,categoria,
    estado,tipo_valvula,diametro_cabeza_mm,diametro_vastago_mm,longitud_total_mm,
    angulo_asiento_grados,diametro_interior_mm,diametro_exterior_mm,dimensiones,
    especificaciones_tecnicas,requiere_revision)
  VALUES(r->>'origen',r->>'fuente_id',r->>'codigo_catalogo',r->>'codigo_oem',r->>'nombre',r->>'subsistema',r->>'categoria',
    'Sin verificar',r->>'tipo_valvula',(r#>>'{medidas,diametro_cabeza_mm}')::numeric,
    (r#>>'{medidas,diametro_vastago_mm}')::numeric,(r#>>'{medidas,longitud_total_mm}')::numeric,
    (r#>>'{medidas,angulo_asiento_grados}')::numeric,(r#>>'{medidas,diametro_interior_mm}')::numeric,
    (r#>>'{medidas,diametro_exterior_mm}')::numeric,r->'dimensiones',r->'especificaciones_tecnicas',
    (r->>'requiere_revision')::boolean)
  ON CONFLICT (catalogo_origen,fuente_registro_id) DO UPDATE SET
    codigo_catalogo=EXCLUDED.codigo_catalogo,codigo_oem=EXCLUDED.codigo_oem,
    nombre=EXCLUDED.nombre,subsistema=EXCLUDED.subsistema,categoria=EXCLUDED.categoria,
    tipo_valvula=EXCLUDED.tipo_valvula,diametro_cabeza_mm=EXCLUDED.diametro_cabeza_mm,
    diametro_vastago_mm=EXCLUDED.diametro_vastago_mm,longitud_total_mm=EXCLUDED.longitud_total_mm,
    angulo_asiento_grados=EXCLUDED.angulo_asiento_grados,diametro_interior_mm=EXCLUDED.diametro_interior_mm,
    diametro_exterior_mm=EXCLUDED.diametro_exterior_mm,dimensiones=EXCLUDED.dimensiones,
    especificaciones_tecnicas=public.repuestos_tecnicos.especificaciones_tecnicas || EXCLUDED.especificaciones_tecnicas,
    requiere_revision=EXCLUDED.requiere_revision,updated_at=now()
  RETURNING id INTO repuesto_uuid;
  FOR codigo_motor IN SELECT jsonb_array_elements_text(r->'motores') LOOP
   SELECT count(*),(array_agg(id))[1] INTO cantidad,motor_uuid FROM public.motores
     WHERE fabricante_id=fabricante_uuid AND upper(btrim(codigo))=upper(btrim(codigo_motor));
   IF cantidad>1 THEN RAISE EXCEPTION 'Motor duplicado: % / %',r->>'fabricante',codigo_motor; END IF;
   IF cantidad=0 THEN
    INSERT INTO public.motores(fabricante_id,codigo,combustible,cilindros,valvulas)
      VALUES(fabricante_uuid,codigo_motor,NULL,NULL,NULL) RETURNING id INTO motor_uuid;
   END IF;
   INSERT INTO public.repuestos_tecnicos_motores(repuesto_id,motor_id)
     VALUES(repuesto_uuid,motor_uuid) ON CONFLICT DO NOTHING;
  END LOOP;
  
  IF jsonb_array_length(r->'motores')=1 THEN
    UPDATE public.repuestos_tecnicos SET motor_id=motor_uuid WHERE id=repuesto_uuid AND motor_id IS NULL;
  END IF;
  
  FOR nombre_modelo IN SELECT jsonb_array_elements_text(r->'modelos') LOOP
   IF btrim(nombre_modelo)<>'' THEN
    INSERT INTO public.modelos(fabricante_id,nombre) SELECT fabricante_uuid,nombre_modelo
    WHERE NOT EXISTS (SELECT 1 FROM public.modelos WHERE fabricante_id=fabricante_uuid AND upper(btrim(nombre))=upper(btrim(nombre_modelo)))
    ON CONFLICT DO NOTHING;
   END IF;
  END LOOP;
  
  FOR referencia IN SELECT jsonb_array_elements_text(r->'referencias') LOOP
   INSERT INTO public.equivalencias_repuestos(repuesto_id,marca_alterna,codigo_alterno,tipo_referencia,notas)
    VALUES(repuesto_uuid,r->>'fabricante',referencia,'Referencia de catálogo','Referencia original del JSON; comprobar compatibilidad antes de usar.')
    ON CONFLICT (repuesto_id,marca_alterna,codigo_alterno) DO NOTHING;
  END LOOP;
  IF r->>'codigo_catalogo' IS NOT NULL THEN
   INSERT INTO public.equivalencias_repuestos(repuesto_id,marca_alterna,codigo_alterno,tipo_referencia,notas)
    VALUES(repuesto_uuid,r->>'origen',r->>'codigo_catalogo','Código de catálogo','Código del fabricante del repuesto, no código OEM.')
    ON CONFLICT (repuesto_id,marca_alterna,codigo_alterno) DO NOTHING;
  END IF;
  cargados:=cargados+1;
 END LOOP;
 RETURN cargados;
END;
$fn$;

